function CreateIPKBMap(recommendations) {
    const result = {};

    recommendations.forEach(rec => {
        const host_name = rec.environment.host_name;
        const ip_address = rec.environment.ip_address;
        const patches = rec.patches;

        const kbList = [
            ...patches.low.map(p => p.advisory),
            ...patches.medium.map(p => p.advisory),
            ...patches.high.map(p => p.advisory),
            ...patches.critical.map(p => p.advisory)
        ].filter(Boolean);

        result[host_name] = {
            "kbs": kbList,
            "server_ip": ip_address
        };
    });

    return result;
};

$host_name_kbs_and_system_info_map = CreateIPKBMap($input_json.recommendations)

function getSystemInfo(ansibleResult) {
  if (!ansibleResult || !ansibleResult.result?.plays) return null;
  const plays = ansibleResult.result.plays;
  const systemInfoByHost = {};
  for (const play of plays) {
    if (!Array.isArray(play.tasks)) continue;
    for (const task of play.tasks) {
      const hosts = task.hosts;
      for (const hostKey in hosts) {
        const host = hosts[hostKey];
        const msg = host["msg"];
        if (msg && (msg["product_name"] || msg["architecture"])) {
          systemInfoByHost[hostKey] = {
            productName: msg["product_name"] || "",
            displayVersion: msg["display_version"] || "",
            architecture: msg["architecture"] || "",
            hostName: msg["host_name"] || "",
            privateIp: msg["private_ip_address"] || "",
            publicIp: msg["public_ip_address"] || "",
            localIp: msg["local_ip"] || ""
          };
        }
      }
    }
  }
  return systemInfoByHost;
}
const hostToKbMap = {}
const systemInfo = getSystemInfo($get_system_info)

for (const [host, kbDetails] of Object.entries($host_name_kbs_and_system_info_map)) {
  let normalizedHost = host
  if (/[a-zA-Z]/.test(host)) {
      normalizedHost = host.split('.')[0]
    }
  let kb_list = kbDetails["kbs"]

  hostToKbMap[normalizedHost] = {
    "kbs": [...kb_list],
    "server_ip": kbDetails["server_ip"]
  };
}


const finalMap = {};

for (const [ip, sysInfo] of Object.entries(systemInfo)) {
  const hostNameKey = sysInfo["hostName"]?.toLowerCase().trim();
  const privateIpKey = sysInfo["privateIp"]?.trim();
  const publicIpKey = sysInfo["publicIp"]?.trim();
  const localIpKey = sysInfo["localIp"]?.trim();

  let kbList = [];
  let server_ip = "";

  if (hostToKbMap[ip]) {
    kbList = [...hostToKbMap[ip]["kbs"]];
    server_ip = hostToKbMap[ip]["server_ip"]
  } else if (privateIpKey && hostToKbMap[privateIpKey]) {
    kbList = [...hostToKbMap[privateIpKey]["kbs"]];
    server_ip = hostToKbMap[privateIpKey]["server_ip"]
  } else if (publicIpKey && hostToKbMap[publicIpKey]) {
    kbList = [...hostToKbMap[publicIpKey]["kbs"]];
    server_ip = hostToKbMap[publicIpKey]["server_ip"]
  } else if (hostNameKey && hostToKbMap[hostNameKey]) {
    kbList = [...hostToKbMap[hostNameKey]["kbs"]];
    server_ip = hostToKbMap[hostNameKey]["server_ip"]
  } else if (localIpKey && hostToKbMap[localIpKey]){
    kbList = [...hostToKbMap[localIpKey]["kbs"]]
    server_ip = hostToKbMap[localIpKey]["server_ip"]
  }

  finalMap[ip] = {
    systemInfo: {
      productName: sysInfo["productName"] || "",
      displayVersion: sysInfo["displayVersion"] || "",
      architecture: sysInfo["architecture"] || "",
      hostName: hostNameKey || "",
      privateIp: privateIpKey || "",
      publicIp: publicIpKey || "",
      serverIp: server_ip || ""
    },
    kbList
  };
}

$host_name_kbs_and_system_info_map = finalMap;
